package com.collegeerp.erp.academic.entity;
import com.collegeerp.erp.academic.enums.*; import com.collegeerp.erp.common.entity.BaseAuditEntity; import com.collegeerp.erp.staff.entity.StaffProfile; import jakarta.persistence.*; import java.time.LocalTime;
@Entity @Table(name="timetable_entries") public class TimetableEntry extends BaseAuditEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="section_id",nullable=false) private Section section; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="subject_id",nullable=false) private Subject subject; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="teacher_id",nullable=false) private StaffProfile teacher; @Enumerated(EnumType.STRING) @Column(name="day_of_week") private TimetableDay dayOfWeek; private LocalTime startTime; private LocalTime endTime; private String roomNumber; @Enumerated(EnumType.STRING) private AcademicStatus status=AcademicStatus.ACTIVE; public Long getId(){return id;} public Section getSection(){return section;} public void setSection(Section v){section=v;} public Subject getSubject(){return subject;} public void setSubject(Subject v){subject=v;} public StaffProfile getTeacher(){return teacher;} public void setTeacher(StaffProfile v){teacher=v;} public TimetableDay getDayOfWeek(){return dayOfWeek;} public void setDayOfWeek(TimetableDay v){dayOfWeek=v;} public LocalTime getStartTime(){return startTime;} public void setStartTime(LocalTime v){startTime=v;} public LocalTime getEndTime(){return endTime;} public void setEndTime(LocalTime v){endTime=v;} public String getRoomNumber(){return roomNumber;} public void setRoomNumber(String v){roomNumber=v;} public AcademicStatus getStatus(){return status;} public void setStatus(AcademicStatus v){status=v;} }
